import java.util.*;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
class Rq {
    // 파싱은 생성할 때 한 번만 하고 조회는 저장한 값을 사용해요.
    private final String action;
    private final Map<String,String> params = new HashMap<>();
    Rq(String command) {
        // 첫 물음표에서만 동작과 쿼리를 나눠요.
        String[] parts = command.split("\\?", 2);
        action = parts[0];
        // 쿼리가 없으면 매개변수는 빈 사전으로 남아요.
        if (parts.length < 2 || parts[1].isEmpty()) return;
        for (String pair : parts[1].split("&")) {
            // 값 안의 등호는 보존해요. 빈 값도 남겨요.
            String[] kv = pair.split("=", 2);
            String key = decode(kv[0]);
            String value = kv.length == 2 ? decode(kv[1]) : "";
            // 같은 키가 반복되면 마지막 값을 선택해요.
            params.put(key, value);
        }
    }
    private String decode(String text) {/*mq3-step-0*/throw new UnsupportedOperationException("아직 구현 전이에요");}
    String action() {/*mq3-step-1*/throw new UnsupportedOperationException("아직 구현 전이에요");}
    // 키가 없을 때만 기본값을 반환해요. 빈 값은 그대로예요.
    String param(String key, String fallback) {/*mq3-step-2*/throw new UnsupportedOperationException("아직 구현 전이에요");}
    int intParam(String key, int fallback) {/*mq3-step-3*/throw new UnsupportedOperationException("아직 구현 전이에요");}
}

